async function imageFrom(url:string){const image=new Image();image.src=url;await image.decode();return image;}
async function blobData(blob:Blob){return new Promise<string>((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result));r.onerror=reject;r.readAsDataURL(blob);});}
async function decodeNarration(blob:Blob){const context=new AudioContext();try{const buffer=await context.decodeAudioData(await blob.arrayBuffer());if(!Number.isFinite(buffer.duration)||buffer.duration<=0)throw Error('Không đọc được thời lượng lời đọc.');return buffer;}finally{await context.close();}}
